use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn weight_at_index(i: int, n: int) -> f32
    requires
        0 <= i < n,
        n > 0,
{
    if i == 0 || i == n - 1 {
        0.5f32
    } else {
        1.0f32
    }
}

fn chebweight(x: Vec<f32>) -> (result: Vec<f32>)
    requires
        x.len() > 0,
    ensures
        result.len() == x.len(),
        forall|i: int| 0 <= i < result.len() ==> 
            result[i] == weight_at_index(i, x.len()),
{
    let n = x.len();
    let mut result = Vec::<f32>::new();
    
    let mut idx: usize = 0;
    
    while idx < n
        invariant
            0 <= idx <= n,
            result.len() == idx as int,
            forall|j: int| 0 <= j < result.len() ==> 
                result[j] == weight_at_index(j, n as int),
        decreases n - idx,
    {
        let weight = if idx == 0 || idx == n - 1 {
            0.5f32
        } else {
            1.0f32
        };
        
        result.push(weight);
        idx = idx + 1;
    }
    
    result
}

}
